  for (var i = 0; i < order.length; i++) {
    var name = order[i];
    var r = builders[name](src, ctx);
    warnings = warnings.concat(r.warnings.map(function (w) {
      return { level: w.level, module: name, msg: w.msg };
    }));
    if (r.module) {
      modulesOut[name] = r.module;
    }
  }

